import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AddProductForm() {
  const [name, setName] = useState('');
  const [variation, setVariation] = useState('');
  const [price, setPrice] = useState('');
  const [description, setDescription] = useState('');
  const [stocks, setStocks] = useState('');
  const [image, setImage] = useState('');
  const navigate = useNavigate();

  const handleFile = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => setImage(reader.result);
    if (file) reader.readAsDataURL(file);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const savedProducts = JSON.parse(localStorage.getItem('products')) || [];
    const newProduct = {
      id: Date.now(),
      name,
      variation,
      price,
      description,
      stocks,
      image
    };
    const updated = [...savedProducts, newProduct];
    localStorage.setItem('products', JSON.stringify(updated));
    navigate('/admin/products');
  };

  return (
    <div className="card">
      <h2>Add Product</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" placeholder="Product Name" value={name} onChange={e => setName(e.target.value)} required />
        <input type="text" placeholder="Variation" value={variation} onChange={e => setVariation(e.target.value)} />
        <input type="number" placeholder="Price" value={price} onChange={e => setPrice(e.target.value)} required />
        <textarea placeholder="Description" value={description} onChange={e => setDescription(e.target.value)} />
        <input type="number" placeholder="Stocks" value={stocks} onChange={e => setStocks(e.target.value)} required />
        <input type="file" onChange={handleFile} />
        <button type="submit">Add Product</button>
      </form>
    </div>
  );
}

export default AddProductForm;
